var TEKS_DATA = [{"mois": "Siban", "annee": 5786, "jours": [{"jour": 1, "soir_debut": "2026-05-18", "soir_fin": "2026-05-19", "ref": "Tehillim 1:1", "texte": "« Heureux l'homme qui ne marche pas selon le conseil des mechants, qui ne s'arrête pas sur la voie des pécheurs et qui ne s'assoit pas en compagnie des moqueurs. »", "texte_kw": "« Benediksyon pou nonm ki pa mache dapre konsèy mechan yo, ki pa kanpe nan chemen pechè yo, epi ki pa chita nan konpayi moun k ap pase tout bagay nan betiz. »"}, {"jour": 2, "soir_debut": "2026-05-19", "soir_fin": "2026-05-20", "ref": "Tehillim 19:8", "texte": "« La Torah de Yahawah est parfaite, elle restaure l'âme. Le témoignage de Yahawah est sûr, il rend sage le simple. »", "texte_kw": "« Torah Yahawah a pafè, li restore nanm nan. Temwayaj Yahawah la sèten, li bay saj moun ki senp. »"}, {"jour": 3, "soir_debut": "2026-05-20", "soir_fin": "2026-05-21", "ref": "Mishle 3:5-6", "texte": "« Confie-toi en Yahawah de tout ton cœur et ne t'appuie pas sur ta propre intelligence. Reconnais-le dans toutes tes voies, et il aplanira tes sentiers. »", "texte_kw": "« Mete konfyans ou nan Yahawah ak tout kè ou, pa konte sou entèlijans pa ou. Rekonèt li nan tout chemen ou yo, epi li pral aplani wout ou yo. »"}, {"jour": 4, "soir_debut": "2026-05-21", "soir_fin": "2026-05-22", "ref": "Yeshayahou 40:31", "texte": "« Ceux qui espèrent en Yahawah renouvellent leur force. Ils prennent leur envol comme des aigles. Ils courent sans se fatiguer, ils marchent sans défaillir. »", "texte_kw": "« Moun ki espere nan Yahawah ap renouvle fòs yo. Y ap pran vòl tankou malfini. Y ap kouri san yo pa fatige, y ap mache san yo pa febli. »"}, {"jour": 5, "soir_debut": "2026-05-22", "soir_fin": "2026-05-23", "ref": "Devarim 6:4-5", "texte": "« Écoute, Yisra'el : Yahawah notre Elohim est le seul Yahawah. Tu aimeras Yahawah ton Elohim de tout ton cœur, de toute ton âme et de toute ta force. »", "texte_kw": "« Koute, Yisra'el : Yahawah Elohim nou an se sèl Yahawah. W ap renmen Yahawah Elohim ou a ak tout kè ou, ak tout nanm ou ak tout fòs ou. »"}, {"jour": 6, "soir_debut": "2026-05-23", "soir_fin": "2026-05-24", "ref": "Maʿasei 2:1-4", "texte": "« Le jour de Shabouʿot étant arrivé, ils étaient tous ensemble dans le même lieu. Soudain il vint du ciel un bruit comme celui d'un vent violent, et il remplit toute la maison où ils étaient assis. »", "texte_kw": "« Lè jou Shabouʿot rive a, yo te tout ansanm nan menm kote a. Toudenkou yon bri soti nan syèl tankou yon van fò, li ranpli tout kay kote yo te chita a. »"}, {"jour": 7, "soir_debut": "2026-05-24", "soir_fin": "2026-05-25", "ref": "Tehillim 92:1-2", "texte": "« Il est bon de louer Yahawah, et de chanter à ton Nom, ô Très-Haut — d'annoncer le matin ta grâce, et ta fidélité pendant les nuits. »", "texte_kw": "« Li bon pou n chante lwanj pou Yahawah, pou n chante pou Non ou, o Trè-Wo — pou n anonse maten an gras ou, ak fidèlite ou pandan lannuit yo. »"}, {"jour": 8, "soir_debut": "2026-05-25", "soir_fin": "2026-05-26", "ref": "Mishle 4:23", "texte": "« Par-dessus tout ce que tu gardes, garde ton cœur, car de lui viennent les sources de la vie. »", "texte_kw": "« Nan tout bagay ou ap veye, veye kè ou, paske se nan li sous lavi yo soti. »"}, {"jour": 9, "soir_debut": "2026-05-26", "soir_fin": "2026-05-27", "ref": "Romiyim 8:28", "texte": "« Nous savons que toutes choses concourent au bien de ceux qui aiment Elohim, de ceux qui sont appelés selon son dessein. »", "texte_kw": "« Nou konnen ke tout bagay travay ansanm pou byenfè moun ki renmen Elohim, moun ki rele dapre plan li. »"}, {"jour": 10, "soir_debut": "2026-05-27", "soir_fin": "2026-05-28", "ref": "Philippiyim 4:6-7", "texte": "« Ne vous inquiétez de rien, mais en toutes choses faites connaître vos besoins à Elohim par des prières et des supplications avec des actions de grâces. »", "texte_kw": "« Pa enkyete pou anyen, men nan tout bagay fè Elohim konnen bezwen ou yo pa lapriyè ak siplikasyon ak remèsiman. »"}, {"jour": 11, "soir_debut": "2026-05-28", "soir_fin": "2026-05-29", "ref": "Yaʿaqov 1:5", "texte": "« Si quelqu'un d'entre vous manque de sagesse, qu'il la demande à Elohim, qui donne à tous simplement et sans reproche, et elle lui sera donnée. »", "texte_kw": "« Si youn nan nou manke sajès, mande l bay Elohim, ki bay tout moun san ezitasyon ak san repwòch, epi y ap ba li l. »"}, {"jour": 12, "soir_debut": "2026-05-29", "soir_fin": "2026-05-30", "ref": "Mattiyahu 6:33", "texte": "« Cherchez premièrement le royaume et la justice d'Elohim, et toutes ces choses vous seront données par-dessus. »", "texte_kw": "« Chèche premye wayòm Elohim a ak jistis li, epi tout lòt bagay sa yo ap ban nou anplis. »"}, {"jour": 13, "soir_debut": "2026-05-30", "soir_fin": "2026-05-31", "ref": "Tehillim 27:1", "texte": "« Yahawah est ma lumière et mon salut — de qui aurais-je crainte ? Yahawah est le soutien de ma vie — de qui aurais-je frayeur ? »", "texte_kw": "« Yahawah se limyè mwen ak delivrans mwen — kisa m ta pè ? Yahawah se sipò lavi mwen — kisa k ta fè m tranble ? »"}, {"jour": 14, "soir_debut": "2026-05-31", "soir_fin": "2026-06-01", "ref": "Ibriyim 5:14", "texte": "« Gwo manje se pou moun ki gen matirite, pou moun ki rive fè diferans ant sa ki byen ak sa ki mal paske yo antrene kapasite yo genyen pou yo gen bon jijman an afòs yo sèvi avè l. »", "texte_kw": "« Gwo manje se pou moun ki gen matirite, pou moun ki rive fè diferans ant sa ki byen ak sa ki mal paske yo antrene kapasite yo genyen pou yo gen bon jijman an afòs yo sèvi avè l. »"}, {"jour": 15, "soir_debut": "2026-06-01", "soir_fin": "2026-06-02", "ref": "Yaḥuānān 14:6", "texte": "« Yahushuʿaḥ lui dit : Je suis le chemin, la vérité et la vie. Nul ne vient au Père que par moi. »", "texte_kw": "« Yahushuʿaḥ di l : Mwen se chemen an, verite a ak lavi a. Pèsòn pa ka rive jwenn Papa a si se pa pa mwen. »"}, {"jour": 16, "soir_debut": "2026-06-02", "soir_fin": "2026-06-03", "ref": "Tehillim 23:1", "texte": "« Yahawah est mon berger : je ne manquerai de rien. Il me fait reposer dans de verts pâturages, il me dirige près des eaux paisibles. »", "texte_kw": "« Yahawah se bèje mwen : m ap pa manke anyen. Li fè m repoze nan zèb vèt, li gide m bò dlo trankil yo. »"}, {"jour": 17, "soir_debut": "2026-06-03", "soir_fin": "2026-06-04", "ref": "Mattiyahu 12:41", "texte": "« Moun Ninbeh yo ap leve nan jijman ansanm ak jenerasyon sa a e y ap kondane l, paske yo te teshoubah apre yo te tande pawòl Yônah yo. Men, gade ! Gen yon moun ki pi enpòtan pase Yônah isit la. »", "texte_kw": "« Moun Ninbeh yo ap leve nan jijman ansanm ak jenerasyon sa a e y ap kondane l, paske yo te teshoubah apre yo te tande pawòl Yônah yo. Men, gade ! Gen yon moun ki pi enpòtan pase Yônah isit la. »", "commentaire": "Lè Yahushuʿah te pale de moun Ninbeh yo, li t ap reponn kèk moun nan jenerasyon pa l la ki te refize koute mesaj Yahawah a malgre tout prèv ak tout ansèyman yo te resevwa. Li te fè referans ak istwa Yônah a, lè Yahawah te voye nabi sa a nan vil Ninbeh pou avèti moun yo sou move chemen yo t ap suiv la. Malgre moun Ninbeh yo pa t fè pati pèp Yisra'el la e yo pa t gen menm nivo konesans ak anpil lòt moun, yo te reyaji avèk imilite lè yo te tande avètisman an. Yo te teshoubah, epi Yahawah te montre yo mizèrikòd li.\n\nLide prensipal la se pa t fè lwanj moun Ninbeh yo kòm moun pafè, men mete aksan sou reyaksyon yo devan avètisman Yahawah la. Yo te dispoze chanje lè yo te konprann yo pa t sou bon chemen an. Okontrè, anpil moun nan jenerasyon Yahushuʿah a te refize koute menm lè yo te devan yon moun ki pi enpòtan pase Yônah.\n\nLè Yahushuʿah di moun Ninbeh yo ap leve nan jijman an, sa montre Yahawah pa bliye moun ki te reyaji pozitivman devan Dabar Li a. Jijman Yahawah toujou chita sou jistis, ekite ak mizèrikòd. Li wè atitid chak moun, fason yo reyaji devan verite a ak sa yo fè ak konesans yo resevwa.\n\nPou Les Membres de La Voie, pasaj sa a se yon rapèl pwisan sou enpòtans imilite ak teshoubah. Moun Ninbeh yo pa t gen tout kantite limyè ak konpreyansyon anpil moun genyen jodi a, men lè yo te tande avètisman Yahawah a, yo te aji. Se sa Yahushuʿah mete an valè.\n\nJodi a tou, tal'midim Yahushuʿah yo bezwen evite pyèj ki fè yon moun kontan tande Dabar la san li pa kite l chanje lavi l. Vrè repons devan Dabar Yahawah a pa sèlman koute oswa aprann; se kite l transfòme e fasone fason n panse, pale ak aji.\n\nMoun Ninbeh yo te tande, yo te konprann, epi yo te teshoubah. Se menm atitid sa a Yahawah ap chèche jwenn lakay tout moun ki vle fè l plèzi yo jodi a.", "liy_final": "Teshoubah pa sèlman fè yon moun vire do bay yon move chemen; li fè l retounen mache nan direksyon Yahawah pou l jwenn mizèrikòd ak tan soulajman."}, {"jour": 18, "soir_debut": "2026-06-04", "soir_fin": "2026-06-05", "ref": "Louqa 19:10", "texte": "« Se moun ki pèdi yo Pitit lòm nan vin chèche, se yo l vin delivre. »", "texte_kw": "« Se moun ki pèdi yo Pitit lòm nan vin chèche, se yo l vin delivre. »", "commentaire": "Pawòl sa yo soti nan epizòd Zakayi a. Zakayi te yon chèf pèseptè taks ki pa t gen bon repitasyon nan je anpil moun. Lè Yahushuʿah te pase nan Yerikho, Zakayi te anvi wè l. Malgre defo ak erè li yo, li te montre yon dezi sensè pou pwoche bò kote Yahawah. Yahushuʿah te pran inisyativ pou l pale avè l epi ale lakay li.\n\nSa te choke anpil moun ki te panse Yahushuʿah pa t dwe asosye ak yon moun konsa. Se nan kontèks sa a Yahushuʿah te deklare pawòl ki nan tèks pou jounen an. Pawòl sa yo montre objektif misyon Yahushuʿah la: li te vini pou ede moun ki pèdi direksyon yo, moun ki chaje ak fot yo, epi moun ki dispoze fè teshoubah lè yo tande Dabar Yahawah la.\n\nZakayi te bay prèv chanjman lè li te ajiste konduit li. Konsa, istwa a montre delivrans pa sèlman konsène padon, men li enplike tou yon transfòmasyon reyèl nan lavi yon moun.\n\nPou Les Membres de La Voie, pasaj sa a raple nou Yahushuʿah pa t vin pou yon ti gwoup moun ki konsidere tèt yo siperyè ak lòt moun. Li te vin chèche moun ki pèdi yo, moun ki bezwen èd, direksyon ak mizèrikòd Yahawah.\n\nSa mande pou tal'midim Yahushuʿah yo devlope menm atitid sa a. Yo pa dwe prese jije moun dapre pase yo, repitasyon yo oswa erè yo te fè. Olye de sa, yo bezwen wè potansyèl ki genyen nan yon moun ki dispoze fè teshoubah epi retounen bò kote Yahawah.\n\nPasaj la raple chak manm La Voie tou ke okenn moun pa dwe panse li twò lwen pou Yahawah ede l. Menm lè yon moun fè anpil erè nan lavi li, si li vin jwenn Yahawah avèk senserite, li kapab jwenn mizèrikòd ak yon nouvo direksyon.", "liy_final": "Yahushuʿah pa t vini pou chèche moun ki panse yo pa bezwen èd; li te vini pou chèche moun ki rekonèt yo bezwen retounen bò kote Yahawah."}, {"jour": 19, "soir_debut": "2026-06-05", "soir_fin": "2026-06-06", "ref": "Marqos 13:10", "texte": "« Fòk yo preche besorah tobah a anvan nan tout nasyon. »", "texte_kw": "« Fòk yo preche besorah tobah a anvan nan tout nasyon. »", "commentaire": "Nan Marqos chapit 13, Yahushuʿah t ap reponn kesyon tal'midim li yo sou evènman ki t ap vini yo ak sou siy ki t ap akonpaye fen sistèm sa a. Li te pale de lagè, tranblemanntè, pèsekisyon ak lòt evènman ki t ap make epòk la. Men, nan mitan tout avètisman sa yo, li te mete aksan sou yon travay ki te dwe fèt anvan fen an rive: pwoklamasyon besorah tobah a.\n\nLè Yahushuʿah te di: \"Fòk yo preche besorah tobah a anvan nan tout nasyon\", li te montre pwoklamasyon mesaj Malkuwt Yahawah a pa t yon travay segondè. Okontrè, li fè pati prensipal objektif li te konfye tal'midim li yo. Travay sa a te kòmanse nan premye syèk la epi li kontinye chak fwa moun fè lòt moun konnen verite ki nan Dabar Yahawah a.\n\nPasaj la montre Yahawah vle tout kalite moun jwenn opòtinite pou tande besorah tobah a. Anvan jijman final la, nasyon yo dwe resevwa temwayaj sa a pou yo ka konnen volonte Yahawah ak chemen Li trase pou lèzòm.\n\nPou Les Membres de La Voie, pasaj sa a raple yo chak tal'mid Yahushuʿah resevwa yon responsabilite nan travay pwoklamasyon an. Se pa sèlman yon kesyon konesans; se yon kesyon pataje ak lòt moun sa Yahawah fè konnen nan Dabar Li a.\n\nTravay sa a kapab fèt nan anpil fason: atravè konvèsasyon chak jou, etid Ketubim Qadoshim yo, emisyon radyo, piblikasyon, entènèt oswa nenpòt lòt mwayen ki pèmèt verite a rive jwenn moun ki ap chèche l.\n\nPasaj sa a ankouraje Les Membres de La Voie pou yo pa dekouraje menm lè rezilta yo pa parèt touswit. Yahushuʿah pa t di tout moun t ap koute, men li te di besorah tobah a dwe preche nan tout nasyon. Se poutèt sa chak tal'mid kapab patisipe selon kapasite l, pandan l sonje se Yahawah ki fè Dabar Li a pote fwi.", "liy_final": "Lè Les Membres de La Voie kontinye soutni travay sa a avèk fidelite, yo montre yo konprann enpòtans misyon Yahushuʿah te konfye tal'midim li yo."}, {"jour": 20, "soir_debut": "2026-06-06", "soir_fin": "2026-06-07", "ref": "Tehillim 100:2", "texte": "« Sèvi Yahawah ak kè kontan. Parèt devan l ak rèl lakontantman. »", "texte_kw": "« Sèvi Yahawah ak kè kontan. Parèt devan l ak rèl lakontantman. »", "commentaire": "Tehillim 100 an se yon chante louwanj ki envite tout moun sou tè a pou yo rekonèt Yahawah kòm Kreyatè yo ak Sila ki pran swen pèp Li a. Chante sa a pa konsantre sou pwoblèm oswa soufrans moun yo, men sou grandè, bonte ak fidelite Yahawah. Se nan kontèks sa a psalmis lan ankouraje moun yo sèvi Yahawah ak kè kontan epi parèt devan Li ak rèl lakontantman.\n\nPawòl sa yo montre adorasyon Yahawah pa ta dwe yon chay oswa yon obligasyon yon moun fè san anvi. Okontrè, lè yon moun konprann kiyès Yahawah ye, tout sa Li fè ak tout mizèrikòd Li manifeste anvè lèzòm, sa bay rezon pou l sèvi Li avèk rekonesans ak lajwa.\n\nTehillim lan kontinye fè konnen se Yahawah ki fè nou e se pou Li nou ye. Li prezante Yahawah kòm yon bèje ki pran swen twoupo Li. Se poutèt sa chante a envite moun yo pwoche bò kote Yahawah avèk rekonesans ak lakontantman.\n\nPou Les Membres de La Voie, pasaj sa a raple yo sèvis y ap rann Yahawah a pa dwe fèt sèlman pa abitid oswa pa obligasyon. Li dwe soti nan yon kè ki rekonesan pou tout sa Yahawah fè pou yo chak jou.\n\nLè tal'midim Yahushuʿah yo reyini pou Shabbat, pou etid Dabar la oswa pou lòt aktivite qehilah a, yo gen yon bèl okazyon pou montre kè kontan yo genyen dèske Yahawah rele yo pou mache nan chemen Li. Menm lè lavi pote eprèv, pwoblèm oswa enkyetid, yo kapab toujou jwenn rezon pou yo rejwi paske yo konnen Yahawah pa abandone moun ki chèche Li avèk senserite.\n\nSèvi Yahawah ak kè kontan pa vle di yon moun pap janm gen moman difisil. Sa vle di menm nan moman sa yo, li kontinye sonje bonte Yahawah, fidelite Li ak tout pwomès Li yo, epi li kontinye sèvi Li avèk yon kè rekonesan.", "liy_final": "Sèvi Yahawah ak kè kontan pa soti nan absans difikilte, men nan yon kè ki rekonèt bonte Yahawah menm nan moman ki pi difisil yo."}, {"jour": 21, "soir_debut": "2026-06-07", "soir_fin": "2026-06-08", "ref": "Mishlé 11:2", "texte": "« Se moun ki konn limit yo ki gen bon konprann. »", "texte_kw": "« Se moun ki konn limit yo ki gen bon konprann. »", "commentaire": "Mishlé 11:2 mete imilite fasafas ak ògèy. Nan premye pati vèsè a, nou li: \"Lè ògèy vini, lawont vini tou.\" Apre sa, li ajoute: \"Se moun ki konn limit yo ki gen bon konprann.\"\n\nNan kontèks la, \"konn limit yo\" pa vle di yon moun manke konfyans oswa li pa gen valè. Okontrè, sa pale de yon moun ki wè tèt li jan li ye toutbon, ki pa egzajere kapasite li, ki pa mete tèt li pi wo pase lòt moun e ki rekonèt li bezwen direksyon Yahawah.\n\nLiv Mishlé a montre plizyè fwa ògèy kapab fè yon moun pran move desizyon paske li sispann koute konsèy oswa li panse li toujou gen rezon. Yon moun ki konn limit li, okontrè, dispoze aprann, reflechi epi aksepte koreksyon lè sa nesesè. Se poutèt sa vèsè a asosye atitid sa a ak bon jijman ak refleksyon.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo enpòtans imilite nan sèvis y ap rann Yahawah la. Yon tal'mid Yahushuʿah pa bezwen chèche parèt pi enpòtan pase sa li ye oswa fè lòt moun wè l kòm yon moun ekstraòdinè. Li bezwen rekonèt tout sa li genyen ak tout sa li aprann soti an premye nan Yahawah.\n\nKonnen limit yon moun ede l evite anpil pwoblèm. Sa ede l pa pran responsabilite li pa pare pou pote, pa fè deklarasyon li pa sèten sou yo epi pa neglije konsèy lòt moun ki gen eksperyans. Yon moun ki gen atitid sa a pi fasil pou l aprann, pou l pwogrese epi pou l kenbe bon relasyon ak lòt tal'mid yo.\n\nPasaj sa a ankouraje Les Membres de La Voie yo pou yo kontinye egzamine tèt yo avèk onètete, aksepte koreksyon lè sa nesesè epi toujou chèche direksyon Yahawah olye pou yo konte sèlman sou pwòp kapasite yo. Lè yo fè sa, yo devlope bon jijman ak refleksyon, epi yo montre vrè matirite roḥanit.", "liy_final": "Se pa moun ki panse li konnen tout bagay ki gen bon jijman ak refleksyon, men moun ki rekonèt limit li epi ki kontinye aprann nan men Yahawah."}, {"jour": 22, "soir_debut": "2026-06-08", "soir_fin": "2026-06-09", "ref": "2 Qorintiyim 7:11", "texte": "« Paske, lefètke nou te vin tris ann akò ak volonte 'Èlohim, ala yon gwo anpresman nou te vin genyen pou nou montre nou pa koupab. »", "texte_kw": "« Paske, lefètke nou te vin tris ann akò ak volonte 'Èlohim, ala yon gwo anpresman nou te vin genyen pou nou montre nou pa koupab. »", "commentaire": "Nan 2 Qorintiyim chapit 7 la, shilliaḥ Šāʾūl ap pale de reyaksyon tal'midim Corinth yo apre yo te resevwa yon koreksyon serye. Okòmansman, koreksyon an te fè yo tris. Men, tristès sa a pa t yon tristès ki mennen nan dekourajman oswa dezespwa. Se te yon tristès ki te ann akò ak volonte Yahawah, yon tristès ki te pouse yo egzamine tèt yo epi fè ajisteman ki nesesè yo.\n\nPou Les Membres de La Voie yo, pasaj sa a montre enpòtans pou yo aksepte koreksyon avèk imilite. Yon tal'mid Yahushuʿah ki gen matirite ap chèche konprann si gen yon bagay li bezwen korije nan konduit li. Si Dabar Yahawah la oswa yon koreksyon ki ekilibre montre yon fot, objektif la pa dwe pwouve li gen rezon, men pito fè sa ki nesesè pou retabli sa ki pa t bon an.", "liy_final": "Lè koreksyon pwodui teshoubah ak chanjman reyèl, li pa vin yon chay; li vin yon mwayen Yahawah itilize pou fè yon tal'mid grandi."}, {"jour": 23, "soir_debut": "2026-06-09", "soir_fin": "2026-06-10", "ref": "Maʿasei 3:19", "texte": "« Kidonk, se pou nou fè teshoubah, e se pou nou kase tèt tounen, pou devyasyon nou yo ka efase, dekwa pou Yahawah li menm fè tan soulajman an rive. »", "texte_kw": "« Kidonk, se pou nou fè teshoubah, e se pou nou kase tèt tounen, pou devyasyon nou yo ka efase, dekwa pou Yahawah li menm fè tan soulajman an rive. »", "commentaire": "Nan Maʿasei chapit 3 la, Képha t ap pale ak yon foul moun apre gerizon yon nonm ki te enfim depi lontan. Li te dirije moun yo sou Yahawah ak sou Yahushuʿah. Li te montre yo yo te bezwen rekonèt erè yo te fè yo epi retounen bò kote Yahawah.\n\nKépha te fè konnen lè yon moun fè sa, devyasyon li yo kapab efase. Li te ajoute tou sa ouvri chemen pou 'tan soulajman' ki soti nan men Yahawah.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo teshoubah se yon eleman esansyèl nan lavi yon tal'mid Yahushuʿah. Yon tal'mid Yahushuʿah pa dwe sèlman rekonèt yon fot; li dwe dispoze kase tèt tounen, sa vle di pran yon nouvo direksyon ki ann amoni ak volonte Yahawah.", "liy_final": "Teshoubah pa sèlman fè yon moun vire do bay yon move chemen; li fè l retounen mache nan direksyon Yahawah pou l jwenn mizèrikòd, restorasyon ak tan soulajman ki soti nan men Li."}, {"jour": 24, "soir_debut": "2026-06-10", "soir_fin": "2026-06-11", "ref": "Tehillim 37:8", "texte": "« Pinga w fache epi w al lage kò w nan fè sa ki mal. »", "texte_kw": "« Pinga w fache epi w al lage kò w nan fè sa ki mal. »", "commentaire": "Tehillim 37 la se yon chante Dāwīd ki ankouraje moun ki sèvi Yahawah yo pou yo pa kite sa y ap wè bò kote yo boulvèse yo. Dāwīd te remake moun ki mechan yo pafwa sanble ap reyisi, pandan moun ki chèche fè sa ki dwat yo konn fè fas ak difikilte ak enjistis.\n\nSe nan kontèks sa a Dāwīd di: 'Pinga w fache epi w al lage kò w nan fè sa ki mal.' Li montre gen yon kalite kòlè ki kapab vin danjere lè yon moun kite l pran kontwòl panse ak aksyon li.\n\nPou Les Membres de La Voie yo, pasaj sa a gen anpil valè nan lavi chak jou. Tal'midim Yahushuʿah yo konn rankontre sitiyasyon ki kapab fè yo fache: enjistis, move pawòl, pwovokasyon, desepsyon oswa konduit lòt moun. Men, Tehillim 37:8 raple yo danje ki genyen lè yon moun kite kòlè dirije reyaksyon li.", "liy_final": "Lè yon tal'mid kite kòlè dirije l, li riske fè sa li t ap kondane a; men lè li kite bon jijman ak refleksyon dirije l, li kontinye mache nan chemen Yahawah la menm nan moman ki difisil yo."}, {"jour": 25, "soir_debut": "2026-06-11", "soir_fin": "2026-06-12", "ref": "Yaḥuānān 6:29", "texte": "« Pou n fè travay 'Èlohim lan, se pou nou demontre nou gen émounah nan moun Li voye a. »", "texte_kw": "« Pou n fè travay 'Èlohim lan, se pou nou demontre nou gen émounah nan moun Li voye a. »", "commentaire": "Nan Yaḥuānān chapit 6 la, foul moun yo te vin jwenn Yahushuʿah apre mirak kote li te bay yon gwo kantite moun manje. Yo te mande l: 'Kisa nou dwe fè pou nou fè travay 'Èlohim yo?' Yahushuʿah te reponn yo: 'Pou n fè travay 'Èlohim lan, se pou nou demontre nou gen émounah nan moun Li voye a.'\n\nAvèk repons sa a, li te montre travay Yahawah apwouve a pa kòmanse ak rit, tradisyon oswa efò lèzòm envante. Li kòmanse ak émounah nan sila Yahawah voye a.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo émounah pa limite ak yon deklarasyon nan bouch sèlman. Yon tal'mid Yahushuʿah demontre émounah li lè li chèche konprann ansèyman Yahushuʿah yo epi mete yo an pratik chak jou.", "liy_final": "Émounah nan sila Yahawah voye a pa sèlman yon bagay yon moun deklare; se yon chemen li chwazi suiv chak jou atravè pawòl li, desizyon li ak konduit li."}, {"jour": 26, "soir_debut": "2026-06-12", "soir_fin": "2026-06-13", "ref": "Ibriyim 3:4", "texte": "« Sila ki konstwi tout bagay yo se 'Èlohim. »", "texte_kw": "« Sila ki konstwi tout bagay yo se 'Èlohim. »", "commentaire": "Nan Ibriyim chapit 3 la, otè a ap fè yon konparezon ant Moshèh ak Yahushuʿah. Se pandan rezonman sa a li fè deklarasyon an: 'Sila ki konstwi tout bagay yo se 'Èlohim.'\n\nPawòl sa yo raple nou lòd, amoni ak objektif nou wè nan linivè a pa soti pa aza. Menm jan yon kay egzije yon moun pou konstwi l, tout sa ki egziste yo montre gen yon Entèlijans ki dèyè yo.\n\nPou Les Membres de La Voie yo, pasaj sa a ankouraje yo pou yo pa janm bliye kiyès ki dèyè tout sa ki egziste yo. Lè yon tal'mid Yahushuʿah reflechi sou kreyasyon an, sou lavi a ak sou fason tout bagay òganize avèk presizyon, sa ranfòse respè li ak admirasyon li pou Yahawah.", "liy_final": "Lè yon tal'mid gade kreyasyon an avèk bon jijman ak refleksyon, li wè dèyè tout sa ki egziste yo men Yahawah, Sila ki konstwi tout bagay yo."}, {"jour": 27, "soir_debut": "2026-06-13", "soir_fin": "2026-06-14", "ref": "1 Qorintiyim 5:1", "texte": "« Yo rapòte gen zenout pami nou, e yon zenout konsa pa menm egziste pami nasyon yo. »", "texte_kw": "« Yo rapòte gen zenout pami nou, e yon zenout konsa pa menm egziste pami nasyon yo. »", "commentaire": "Nan 1 Qorintiyim chapit 5 la, shilliaḥ Šāʾūl t ap adrese yon sitiyasyon grav ki te parèt nan qehilah Corinth la. Pwoblèm nan pa t sèlman konduit mesye a, men lefètke qehilah a pa t sanble reyalize gravite sitiyasyon an.\n\nŠāʾūl te itilize okazyon sa a pou montre enpòtans pwòpte moral pami moun k ap mache nan chemen Yahushuʿah la. Li te fè konprann qehilah a pa dwe fèmen je sou konduit ki kontinye vyole prensip Yahawah yo.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo pwòpte moral pa yon kestyon segondè. Yon tal'mid Yahushuʿah bezwen fè efò pou lavi li ann amoni ak prensip Yahawah yo, pa sèlman an piblik, men tou nan lavi prive li.", "liy_final": "Pwòpte moral pa sèlman pwoteje yon tal'mid; li pwoteje tou qehilah a epi li onore prensip Yahawah yo."}, {"jour": 28, "soir_debut": "2026-06-14", "soir_fin": "2026-06-15", "ref": "Yaḥuānān 3:16", "texte": "« Paske, 'Èlohim tèlman renmen monn nan, li bay sèl Pitit Gason li fè a pou li, dekwa pou nenpòt moun ki demontre l gen émounah nan li pa detwi, men pou l gen lavi ki pap janm fini an. »", "texte_kw": "« Paske, 'Èlohim tèlman renmen monn nan, li bay sèl Pitit Gason li fè a pou li, dekwa pou nenpòt moun ki demontre l gen émounah nan li pa detwi, men pou l gen lavi ki pap janm fini an. »", "commentaire": "Nan Yaḥuānān chapit 3 la, Yahushuʿah t ap pale ak Nikodèm. Vèsè sa a montre pwofondè lanmou Yahawah pou limanite. Li montre Yahawah pa t rete endiferan devan sitiyasyon lèzòm ki te anba konsekans devyasyon yo. Okontrè, Li te pran inisyativ pou bay Pitit Gason Li a pou ouvri chemen ki mennen nan lavi.\n\nPasaj la montre tou lavi ki pap janm fini an pa yon bagay lèzòm kapab achte oswa merite pa pwòp fòs yo. Li se yon kado ki soti nan lanmou Yahawah.\n\nPou Les Membres de La Voie yo, pasaj sa a se youn nan pi gwo prèv ki montre jan lanmou Yahawah depase sa lèzòm kapab imajine. Li raple tal'midim Yahushuʿah yo relasyon yo ak Yahawah pa baze sou merit pèsonèl yo, men sou lanmou, mizèrikòd ak dispozisyon Yahawah pran pou ede lèzòm.", "liy_final": "Yaḥuānān 3:16 raple nou pi gwo prèv lanmou Yahawah te montre lèzòm se dispozisyon Li pran pou yo jwenn lavi."}, {"jour": 29, "soir_debut": "2026-06-15", "soir_fin": "2026-06-16", "ref": "Mattiyahu 26:41", "texte": "« Kontinye veye e kontinye hitpallél pou nou pa tonbe nan tantasyon. Se vre, rouaḥ a byen dispoze, men chè a fèb. »", "texte_kw": "« Kontinye veye e kontinye hitpallél pou nou pa tonbe nan tantasyon. Se vre, rouaḥ a byen dispoze, men chè a fèb. »", "commentaire": "Pawòl sa yo te soti nan dènye nuit anvan arestasyon Yahushuʿah. Apre Seʿoudat ha'Adôn nan, li te ale ak tal'midim li yo nan Gan Gat-Shmanim. Li te konnen gwo eprèv t ap rive sou li e li te ankouraje tal'midim yo pou yo rete vijilan.\n\nYahushuʿah te konprann tal'midim yo te gen bon entansyon. Yo te renmen l e yo te vle rete fidèl. Men, li te konnen tou lèzòm gen limit. Se poutèt sa li te ajoute: 'Se vre, rouaḥ a byen dispoze, men chè a fèb.'\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo enpòtans vijilans nan lavi roḥanit la. Li pa sifi sèlman pou yon tal'mid gen bon entansyon oswa renmen Yahawah. Li bezwen tou rete vijilan epi kontinye hitpallél pou l jwenn fòs pou fè fas ak eprèv, tantasyon ak presyon lavi yo.", "liy_final": "Vijilans ak hitpallah mache ansanm. Lè yon tal'mid kontinye veye epi kontinye hitpallél, li pi byen prepare pou l rete fèm lè eprèv ak tantasyon yo rive."}, {"jour": 1, "soir_debut": "2026-06-16", "soir_fin": "2026-06-17", "ref": "Romiyim 5:10", "texte": "« Paske, si lè nou te ènmi 'Èlohim, nou te vin rekonsilye avè l grasa lanmò Pitit li a, alewè pou kounye a nou vin rekonsilye avè l! »", "texte_kw": "« Paske, si lè nou te ènmi 'Èlohim, nou te vin rekonsilye avè l grasa lanmò Pitit li a, alewè pou kounye a nou vin rekonsilye avè l! »", "commentaire": "Nan Romiyim chapit 5 la, shilliaḥ Šāʾūl ap esplike byenfè ki soti nan sa Yahawah fè atravè Yahushuʿah. Li montre lèzòm pa t kapab retabli relasyon yo ak Yahawah pa pwòp efò pa yo. Devyasyon te kreye yon separasyon ant lèzòm ak Yahawah, sa ki fè tout moun te bezwen rekonsilyasyon.\n\nŠāʾūl fè konnen, menm lè lèzòm te nan yon pozisyon opozisyon ak objektif Yahawah yo, Yahawah te pran inisyativ pou ouvri chemen rekonsilyasyon an grasa lanmò Pitit Li a.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon gwo rapèl sou valè rekonsilyasyon Yahawah ofri a. Li montre pèsonn pa dwe panse li twò lwen oswa twò chaje ak fot pou Yahawah pa kapab resevwa l ankò.", "liy_final": "Si Yahawah te fè rekonsilyasyon posib lè nou te lwen Li, nou kapab gen konfyans Li kapab kontinye soutni, gide ak delivre moun ki rete atache ak Li atravè Yahushuʿah.", "mois": "Rebi'i"}, {"jour": 2, "soir_debut": "2026-06-17", "soir_fin": "2026-06-18", "ref": "2 Corinthiyim 7:10", "texte": "« Anfèt, tristès ki ann akò ak volonte 'Èlohim pwodui yon teshoubah ki mennen nan delivrans, e yon moun pa bezwen regrèt sa; men tristès ki soti nan monn nan pwodui lanmò. »", "texte_kw": "« Anfèt, tristès ki ann akò ak volonte 'Èlohim pwodui yon teshoubah ki mennen nan delivrans, e yon moun pa bezwen regrèt sa; men tristès ki soti nan monn nan pwodui lanmò. »", "commentaire": "Nan dezyèm lèt li te voye bay qehilah Corinth la, shilliaḥ Šāʾūl t ap reflechi sou efè koreksyon li te fè yo anvan. Okòmansman, lèt li a te lakòz anpil tristès nan mitan yo, men tristès sa a pa t yon tristès san espwa. Okontrè, li te pouse yo egzamine konduit yo, rekonèt fot yo epi fè teshoubah.\n\nSe nan kontèks sa a Šāʾūl fè diferans ant de kalite tristès. Gen yon tristès ki ann akò ak volonte Yahawah, ki touche kè yon moun epi pouse l chanje lavi li. Tristès sa a pwodui teshoubah, retabli relasyon ak Yahawah epi mennen nan delivrans. Men, gen yon lòt tristès ki soti nan monn nan: li kapab lakòz dezespwa, wont oswa remò san okenn chanjman reyèl. Kalite tristès sa a pa pwodui lavi; li mennen nan lanmò.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo koreksyon ki soti nan Dabar Yahawah pa fèt pou kraze yon moun, men pou ede l retounen sou bon chemen an. Lè yon tal’mid rekonèt erè li epi li kite tristès ki ann akò ak volonte Yahawah manyen kè li, sa dwe pouse l fè teshoubah epi mache pi pre Yahawah.\n\nPasaj la ankouraje chak tal’mid pou l pa kache fot li oswa fè tèt di lè yo montre l yon erè. Okontrè, li dwe akeyi koreksyon avèk imilite, paske objektif li se restorasyon, pa kondanasyon. Yon moun ki vrèman renmen Yahawah pap sèlman santi l tris poutèt sa li fè ki mal; li pral pran mezi konkrè pou l chanje.\n\nNan menm sans lan, Les Membres de La Voie yo dwe fè atansyon pou yo pa tonbe nan tristès monn nan, ki fè yon moun dekouraje oswa abandone tout espwa. Yahawah vle yon tristès ki mennen nan teshoubah, nan gerizon roḥanit ak nan yon lavi ki pi pwòch ak Li.", "liy_final": "Lè tristès pouse yon moun fè teshoubah epi retounen jwenn Yahawah, li vin tounen yon chemen ki mennen nan delivrans olye li mennen nan dezespwa.", "mois": "Rebi'i"}, {"jour": 3, "soir_debut": "2026-06-18", "soir_fin": "2026-06-19", "ref": "Ibriyim 10:33", "texte": "« Gen lè yo te fè nou sibi jouman ak soufrans devan tout moun; gen lòt lè, nou te chwazi soutni moun ki t ap pase anba menm eprèv sa yo. »", "texte_kw": "« Gen lè yo te fè nou sibi jouman ak soufrans devan tout moun; gen lòt lè, nou te chwazi soutni moun ki t ap pase anba menm eprèv sa yo. »", "commentaire": "Lè otè lèt pou Ibriyim yo te ekri pawòl sa yo, li t ap ankouraje tal’mid yo pou yo pa lage fèmte yo malgre opozisyon yo t ap rankontre. Anpil nan yo te deja sibi imilyasyon piblik, pèsekisyon ak soufrans poutèt yo te chwazi suiv Yahushuʿah. Gen lòt ki pa t viktim dirèkteman, men yo te demontre lanmou ak fidelite lè yo te kanpe bò kote frè ak sè yo ki t ap sibi eprèv yo, olye yo te pran distans pou pwoteje pwòp enterè pa yo.\n\nOtè a raple yo konduit sa a te fè pati fidelite yo anvè Yahawah. Li ankouraje yo pou yo sonje andirans yo te montre nan tan lontan, epi pou yo kontinye kenbe menm detèminasyon an jiskaske yo resevwa pwomès Yahawah yo.\n\nPou Les Membres de La Voie yo jodi a, pasaj sa a raple nou ke mache sou Ha’Derekh la pa toujou fasil. Ka rive gen moman kote yon tal’mid sibi kritik, mepri oswa lòt kalite opozisyon poutèt fidélite li anvè Dabar Yahawah. Nan moman konsa, li enpòtan pou l rete fèm epi sonje Yahawah wè tout sa l ap andire.\n\nMen pasaj la montre yon lòt leson enpòtan toujou: nou pa dwe abandone moun k ap travèse eprèv yo. Lè youn nan nou anba presyon, anba enjistis oswa anba difikilte poutèt fidelite li, rès qehilah la dwe montre lanmou, ankourajman ak solidarite. Soutni yon tal’mid ki nan tribilasyon se yon fason pou nou montre nou menm tou nou fidèl anvè Yahawah.\n\nKonsa, olye pou pèsekisyon divize nou, li ta dwe fè nou vin pi ini, pi dispoze pote chay youn lòt, epi kontinye avanse ansanm avèk kouraj sou chemen Yahawah mete devan nou.", "mois": "Rebi'i"}, {"jour": 5, "soir_debut": "2026-06-20", "soir_fin": "2026-06-21", "ref": "Yaʿaqob 1:5", "texte_kw": "« Si youn nan nou manke bon konprann, se pou l kontinye mande 'Èlohim li, e l ap ba li l, paske l donan ak tout moun, e li pa fè repwòch. »", "commentaire": "Nan kòmansman lèt li a, Yaʿaqob ap ankouraje tal'midim yo pou yo kenbe fèm lè yo rankontre divès kalite eprèv. Li montre eprèv yo kapab ede yon moun devlope andirans ak matirite. Men, pou fè fas ak sitiyasyon sa yo yon fason ki fè Yahawah plezi, yon moun bezwen bon konprann.\n\nSe nan kontèks sa a Yaʿaqob di: \"Si youn nan nou manke bon konprann, se pou l kontinye mande 'Èlohim li.\" Bon konprann li pale a pa limite ak konesans oswa entèlijans. Li se kapasite pou konprann volonte Yahawah epi aplike Dabar Li a avèk bon jijman nan sitiyasyon lavi yo.\n\nYaʿaqob mete aksan sou jenewozite Yahawah. Li pa dekouraje moun ki pwoche bò kote Li avèk senserite; okontrè, Li dispoze bay direksyon ak bon konprann san Li pa fè repwòch moun ki mande avèk yon kè sensè.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo pa gen okenn wont pou rekonèt limit pa yo epi chèche direksyon Yahawah. Chak jou pote desizyon, defi ak eprèv ki mande plis pase eksperyans lèzòm; yo mande bon konprann ki soti nan Yahawah.\n\nLè yon tal'mid ap fè fas ak yon chwa enpòtan, yon pwoblèm fanmi, yon desizyon nan qehilah a oswa yon eprèv pèsonèl, li pa dwe konte sèlman sou pwòp refleksyon pa li. Li dwe hitpallél, etidye Ketubim Qadoshim yo epi chèche konprann prensip Yahawah yo pou l ka pran desizyon ki ann amoni ak volonte Li.\n\nPasaj sa a ankouraje Les Membres de La Voie yo tou pou yo gen konfyans nan jenerozite Yahawah. Lè yo mande Li bon konprann avèk émounah ak yon kè ki dispoze obeyi, yo kapab gen asirans Li ap gide yo atravè Dabar Li a epi ede yo mache sou bon chemen an.", "liy_final": "Vrè bon konprann pa soti nan kapasite lèzòm sèlman; li soti nan Yahawah e Li bay li avèk jenerozite bay moun ki chèche Li avèk yon kè sensè.", "mois": "Rebi'i"}, {"jour": 6, "soir_debut": "2026-06-21", "soir_fin": "2026-06-22", "ref": "Yeshaʿeyahou 65:13", "texte_kw": "« Se poutèt sa, men sa Yahawah Adôn ki Souvren an di: 'Gade! ʿEbedim mwen yo ap manje, men nou menm n ap grangou. Gade! ʿEbedim mwen yo ap bwè, men nou menm n ap swaf. Gade! ʿEbedim mwen yo ap rejwi, men nou menm n ap wont.' »", "commentaire": "Nan dènye chapit liv Yeshaʿeyahou a, Yahawah fè yon diferans klè ant de kategori moun. Sou yon bò, gen moun ki vire do bay Li, ki suiv pwòp chemen pa yo epi ki meprize volonte Li. Sou lòt bò, gen ʿEbedim Li yo, moun ki chèche sèvi Li avèk fidelite epi ki dispoze koute Dabar Li a.\n\nSe nan kontèks sa a Yahawah anonse yon kontrast frapan: ʿEbedim Li yo ap jwenn manje, bwason ak lajwa, tandiske moun ki rejte Li yo ap fè eksperyans grangou, swaf ak wont. Pawòl sa yo sèvi pou montre benediksyon Yahawah pa depann sèlman de richès materyèl, men sitou de relasyon yon moun genyen avèk Li ak favè Li akòde a.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon ankourajman pou yo kontinye rete fidèl ak Yahawah menm lè yo ap viv nan yon monn ki souvan chwazi yon lòt direksyon. Yahawah pa bliye ʿEbedim Li yo. Li konnen bezwen yo epi Li pran swen yo selon volonte Li.\n\nPasaj la ankouraje tal'midim Yahushuʿah yo pou yo chèche an premye sa ki gen valè devan Yahawah. Menm lè yo konfwonte difikilte oswa privasyon, yo kapab gen konfyans Yahawah ap soutni yo epi ba yo sa yo bezwen pou kontinye mache sou chemen Li.\n\nAn menm tan, vèsè sa a envite chak moun egzamine pwòp pozisyon li. Èske li ap viv kòm yon ʿEbed Yahawah ki koute Dabar Li a, oswa èske li ap suiv pwòp volonte pa li? Vrè lajwa, vrè satisfaksyon ak vrè espwa jwenn rasin yo nan fidelite anvè Yahawah.", "liy_final": "Yahawah fè yon diferans ant moun ki sèvi Li avèk fidelite ak moun ki vire do bay Li. Se poutèt sa, Les Membres de La Voie yo chwazi mache kòm ʿEbedim Yahawah, avèk konfyans ke Li pap janm abandone moun ki rete atache ak Li.", "mois": "Rebi'i"}, {"jour": 7, "soir_debut": "2026-06-22", "soir_fin": "2026-06-23", "ref": "Colossiyim 4:6", "texte_kw": "« Se pou pawòl nou toujou bèl, se pou l asezonnen ak sèl, yon fason pou n konnen jan n dwe reponn chak moun. »", "commentaire": "Nan fen lèt li te voye bay qehilah Coloss la, shilliaḥ Šāʾūl bay plizyè konsèy pratik sou fason pou tal'midim Yahushuʿah yo viv chak jou. Li ankouraje yo pou yo sèvi ak tan yo avèk bon jijman, sitou lè y ap pale ak moun ki pa fè pati qehilah a.\n\nSe nan kontèks sa a li di: \"Se pou pawòl nou toujou bèl, se pou l asezonnen ak sèl.\" Alò, nan tan lontan, sèl te sèvi pou konsève manje epi ba l bon gou. Menm jan an tou, pawòl yon tal'mid pa dwe ni brital ni san valè; pawòl yo dwe itil, ankourajan, reflechi epi adapte ak sitiyasyon chak moun.\n\nObjektif la se pou moun k ap pale a konnen kijan pou l bay yon repons ki montre l gen bon konprann, ki respekte laverite epi ki kapab ede moun k ap koute a.\n\nPou Membres La Voie yo, pasaj sa a raple yo pawòl yo gen anpil enpòtans. Yon tal'mid Yahushuʿah pa sèlman rekonèt apati de aksyon l sèlman, men tou pa fason l pale ak lòt moun. Kit se nan fanmi, nan travay, nan qehilah a oswa sou rezo sosyal yo, pawòl li dwe montre metriz, respè ak bon jijman.\n\n\"Asezonnen ak sèl\" vle di chwazi mo ki bati olye yo kraze, ki klè san yo pa blese initilman, epi ki fidèl ak Dabar Yahawah a. Sa pa vle di evite laverite, men pito prezante l avèk dousè, pasyans ak konsiderasyon pou moun k ap koute a.\n\nPasaj sa a ankouraje Membres La Voie yo tou pou yo adapte repons yo selon moun ak sikonstans yo. Gen moun ki bezwen ankourajman, gen lòt ki bezwen koreksyon, epi gen lòt ankò ki bezwen plis eksplikasyon. Bon jijman pèmèt yon tal'mid konnen ki pawòl ki pi apwopriye nan chak sitiyasyon.", "liy_final": "Pawòl ki soti nan bouch yon tal'mid Yahushuʿah dwe pote gou, limyè ak lavi, pou yo onore Yahawah epi ede lòt moun pwoche pi pre Dabar Li a.", "mois": "Rebi'i"}, {"jour": 8, "soir_debut": "2026-06-23", "soir_fin": "2026-06-24", "ref": "1 Shemuʾel 17:45", "texte_kw": "« Ou menm, ou vin sou mwen ak nepe, ak frenn ak javlo; men mwen menm, mwen vin sou ou nan Non Yahawah Tseba'oth, 'Èlohim lame Yisra'el yo, Sila ou derespekte a. »", "commentaire": "Pasaj sa a pran plas pandan gwo konfwontasyon ant Dāwīḍ ak Golyath, yon vanyan sòlda filisten ki t ap defye pèp Yisra'el la epi k ap derespekte Non Yahawah. Pandan tout lame Yisra'el la te pè devan gwosè ak fòs Golyath, Dāwīḍ pa t kite aparans oswa zam advèsè li a fè l pè.\n\nLè Golyath vin sou li ak nepe, frenn ak javlo, Dāwīḍ reponn li avèk konfyans total nan Yahawah. Li fè konnen viktwa pa depann de fòs fizik oswa zam lagè, men de Yahawah Tseba'oth, Sila ki gen tout pouvwa e ki defann Non Li ak pèp Li. Pawòl Dāwīḍ yo montre batay la pa t sèlman ant de moun; se te yon kestyon fidelite anvè Yahawah ak respè pou Non Li.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo ke pi gwo sous fòs yon tal'mid pa chita nan kapasite pèsonèl li, ni nan resous materyèl li genyen, men nan konfyans li mete nan Yahawah. Nan lavi chak jou, anpil \"Golyath\" kapab parèt sou fòm eprèv, opozisyon, pèsekisyon, maladi oswa lòt defi ki sanble depase fòs nou.\n\nEgzanp Dāwīḍ ankouraje tal'midim Yahushuʿah yo pou yo pa kite laperèz oswa aparans sitiyasyon yo pran kontwòl sou yo. Lè yo rete fidèl ak Yahawah, yo ka avanse avèk kouraj, paske yo konnen se pa fòs lèzòm ki deside rezilta final la.\n\nPasaj sa a montre tou enpòtans pou toujou defann onè Non Yahawah avèk respè ak fidélité. Menm lè majorite a dekouraje oswa pè, yon sèl moun ki mete konfyans li nan Yahawah kapab sèvi kòm yon gwo temwayaj pou lòt moun.", "liy_final": "Lè yon tal'mid mete tout konfyans li nan Yahawah olye li konte sou fòs lèzòm, li aprann fè fas ak pi gwo eprèv yo avèk kouraj, paske li konnen Yahawah pa abandone moun ki rete fidèl ak Li.", "mois": "Rebi'i"}, {"jour": 9, "soir_debut": "2026-06-24", "soir_fin": "2026-06-25", "ref": "Yeshaʿeyahou 41:10", "texte_kw": "« Ou pa bezwen pè, paske mwen avè w. Pa bay tèt ou pwoblèm, paske mwen se 'Èlohim ou. M ap ba w fòs, wi, m ap ede w. Vrèmanvre, m ap kenbe w byen di ak men dwat mwen pou m mennen w nan chemen ki dwat la. »", "commentaire": "Nan Yeshaʿeyahou chapit 41 la, Yahawah ap pale ak pèp Yisra'el la nan yon epòk kote yo t ap fè fas ak gwo menas, ensekirite ak dekourajman. Pandan nasyon ki ozalantou yo t ap mete konfyans yo nan zidòl ak nan pwòp fòs yo, Yahawah raple pèp Li a se Li menm ki te chwazi yo epi ki pa t abandone yo.\n\nSe nan kontèks sa a Li di: \"Ou pa bezwen pè, paske mwen avè w.\" Pawòl sa yo se yon mesaj rekonfò ak ankourajman. Yahawah pwomèt prezans Li, soutyen Li ak fòs Li pou moun ki mete konfyans yo nan Li. Men dwat Li mansyone a senbolize pouvwa, jistis ak fidelite Li pou gide ak soutni ʿEbedim Li yo.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon sous ankourajman nan tout kalite eprèv. Gen moman kote yon tal'mid ka santi l fèb, poukont li oswa enkyete devan difikilte lavi yo. Men Yahawah raple nou prezans Li pa depann de sikonstans yo; Li rete avèk moun ki chèche mache nan chemen Li.\n\nPasaj la ankouraje tal'midim Yahushuʿah yo pou yo pa kite laperèz dirije desizyon yo. Olye de sa, yo dwe chèche fòs nan Yahawah atravè hitpallah, etid Dabar Li a ak fidélité chak jou. Lè yon moun konte sou Yahawah, li jwenn kouraj pou kontinye menm lè chemen an difisil.\n\nAnplis, pwomès Yahawah pou \"kenbe nou byen di ak men dwat Li\" raple nou Li pa sèlman bay enstriksyon; Li soutni, gide epi ede moun ki rete fidèl yo. Sa envite Les Membres de La Voie yo pou yo mete tout konfyans yo nan Li olye yo konte sèlman sou kapasite pa yo oswa sou èd lèzòm.", "liy_final": "Lè yon tal'mid mache avèk Yahawah, li pa bezwen kite laperèz domine l, paske Yahawah pwomèt Li ap ba li fòs, ede l epi kenbe l fèm sou chemen ki dwat la.", "mois": "Rebi'i"}, {"jour": 10, "soir_debut": "2026-06-25", "soir_fin": "2026-06-26", "ref": "Malʾakhi 3:18", "texte_kw": "« Yon lòt fwa ankò, n ap wè diferans ant yon moun ki jis ak yon moun ki mechan, ant yon moun k ap sèvi 'Èlohim ak yon moun ki pap sèvi l. »", "commentaire": "Nan dènye chapit liv Malʾakhi a, Yahawah reponn ak pawòl kèk moun ki t ap di li pa vo sèvi Li, paske yo te panse moun ki fè sa ki mal yo sanble ap reyisi pandan moun ki rete fidèl yo pa jwenn okenn avantaj. Anfas panse sa yo, Yahawah fè konnen Li wè tout bagay e Li pa bliye moun ki gen krentif pou Non Li.\n\nSe nan kontèks sa a Li pwomèt yon lè ap rive kote diferans lan ap parèt aklè. Moun ki mache nan jistis ak moun ki chwazi mechanste pap resevwa menm rezilta. Menm jan an tou, moun ki sèvi Yahawah fidèlman ak moun ki refize sèvi Li pap gen menm avni. Jijman Yahawah ap revele sa ki te pafwa kache nan je lèzòm.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon envitasyon pou yo pa kite aparans twonpe yo. Nan monn jodi a, li ka sanble pafwa moun ki pa suiv chemen Yahawah la ap viv san pwoblèm oswa ap reyisi plis. Men Malʾakhi raple nou Yahawah pa jije selon aparans; Li konnen kè chak moun epi Li fè diferans ant fidelite ak ipokrizi.\n\nTal'midim Yahushuʿah yo pa dwe sèvi Yahawah sèlman pou benefis materyèl oswa pou yo jwenn lwanj nan men moun. Yo sèvi Li paske yo renmen Li, yo mete émounah yo nan Li epi yo rekonèt chemen Li se chemen lavi.\n\nPasaj sa a ankouraje chak manm La Voie pou l egzamine pwòp lavi li. Kesyon ki pi enpòtan an se pa sa lòt moun panse de nou, men si Yahawah rekonèt nou kòm moun k ap sèvi Li avèk yon kè sensè. Lè jou a rive kote Li fè diferans lan parèt aklè, se fidelite, obeyisans ak andirans ki pral konte.", "liy_final": "Yahawah pa janm konfonn moun ki sèvi Li ak moun ki vire do ba Li. Menm si diferans lan pa toujou parèt jodi a, lè Li a rive, Li menm ap fè l parèt aklè devan tout moun.", "mois": "Rebi'i"}, {"jour": 11, "soir_debut": "2026-06-26", "soir_fin": "2026-06-27", "ref": "Éphésiyim 6:4", "texte_kw": "« E nou menm papa, pa nwi pitit nou jiskaske nou fè yo fache, men kontinye leve yo nan disiplin Yahawah ak nan avètisman Li bay. »", "commentaire": "Nan Éphésiyim chapit 6 la, shilliaḥ Šāʾūl bay enstriksyon sou relasyon ki dwe egziste anndan fanmi an. Apre li fin pale sou devwa timoun yo anvè paran yo, li vire bò kote papa yo epi li ba yo yon responsablite enpòtan. Li avèti yo pou yo pa trete pitit yo yon fason ki dekouraje yo, ki fè yo pèdi kouraj oswa ki pwovoke yo san rezon.\n\nOkontrè, Šāʾūl ankouraje yo pou yo leve pitit yo nan disiplin Yahawah ak nan avètisman ki soti nan Dabar Li a. Objektif disiplin sa a se pa kraze pitit la, men ede l grandi avèk bon prensip, bon jijman ak respè pou Yahawah.\n\nPou Les Membres de La Voie yo, pasaj sa a montre paran yo resevwa yon misyon sakre. Leve yon timoun pa sèlman vle di bay manje, rad oswa edikasyon; sa mande tou pou fòme karaktè li selon prensip Yahawah.\n\nPapa ak manman yo dwe evite move kòlè, enjistis, imilyasyon oswa egzije plis pase sa yon timoun kapab pote. Disiplin ki soti nan Yahawah chèche korije avèk lanmou, pasyans ak regilarite, pou pitit la aprann fè sa ki dwat pa konviksyon olye de laperèz.\n\nPasaj la ankouraje tout fanmi ki nan La Voie pou yo fè lakay yo tounen yon kote kote Dabar Yahawah li, etidye epi mete an pratik. Lè paran yo bay bon egzanp nan pawòl ak nan konduit yo, yo ede pitit yo devlope yon émounah solid epi prepare yo pou rete fidèl devan eprèv lavi yo.", "liy_final": "Disiplin ki baze sou Dabar Yahawah pa kraze yon timoun; li fòme l, pwoteje l epi prepare l pou l mache avèk fidelite sou chemen Yahawah pandan tout lavi li.", "mois": "Rebi'i"}]}, {"mois": "Rebi'i", "annee": 5786, "jours": [{"jour": 1, "soir_debut": "2026-06-16", "soir_fin": "2026-06-17", "ref": "Romiyim 5:10", "texte_kw": "« Paske, si lè nou te ènmi 'Èlohim, nou te vin rekonsilye avè l grasa lanmò Pitit li a, alewè pou kounye a nou vin rekonsilye avè l! »"}, {"jour": 2, "soir_debut": "2026-06-17", "soir_fin": "2026-06-18", "ref": "2 Corinthiyim 7:10", "texte_kw": "« Anfèt, tristès ki ann akò ak volonte 'Èlohim pwodui yon teshoubah ki mennen nan delivrans, e yon moun pa bezwen regrèt sa; men tristès ki soti nan monn nan pwodui lanmò. »"}, {"jour": 3, "soir_debut": "2026-06-18", "soir_fin": "2026-06-19", "ref": "Ibriyim 10:33", "texte_kw": "« Gen lè yo te fè nou sibi jouman ak soufrans devan tout moun; gen lòt lè, nou te chwazi soutni moun ki t ap pase anba menm eprèv sa yo. »"}, {"jour": 4, "soir_debut": "2026-06-19", "soir_fin": "2026-06-20", "ref": "Maʿasei 18:8", "texte_kw": "« Crispus, responsab beit haknesset la, te vin demontre li gen émounah nan Adôn nan ansanm ak tout moun lakay li. Menm jan an tou, anpil moun nan Corinthe ki te tande Dabar la te vin gen émounah epi yo te thabalé. »", "commentaire": "Lè shilliaḥ Šāʾūl te rive Corinthe, li te pase anpil tan ap anonse Besorah Tobah a bay moun nan vil la. Okòmansman, li te rankontre opozisyon nan mitan kèk moun, men sa pa t anpeche Dabar Yahawah la kontinye fè efè sou anpil lòt. Se nan kontèks sa a Crispus, responsab beit haknesset la, ansanm ak tout moun lakay li, te vin demontre yo gen émounah nan Yahushuʿah.\n\nVèsè a ajoute ke anpil lòt moun nan Corinthe te suiv menm chemen an. Yo te kòmanse pa koute Dabar la, apre sa yo te devlope émounah, epi finalman yo te thabalé. Lòd sa a montre émounah pa t baze sou tradisyon oswa presyon sosyal, men sou konpreyansyon ak akseptasyon Dabar Yahawah la.\n\nPou Les Membres de La Voie yo, pasaj sa a montre enpòtans pou yon moun koute Dabar Yahawah la avèk yon kè ouvè. Se lè Dabar la antre nan kè yon moun li kapab devlope yon émounah ki solid epi pran desizyon pou l mache nan chemen Yahushuʿah la.\n\nEgzanp Crispus montre tou pozisyon oswa responsabilite yon moun pa dwe anpeche l aksepte verite a. Malgre li te gen yon fonksyon enpòtan nan beit haknesset la, li te dispoze suiv sa Dabar Yahawah la te montre l.\n\nPou tal'midim Yahushuʿah yo jodi a, pasaj sa a raple yo ke émounah reyèl la dwe mennen nan aksyon. Menm jan moun Corinthe yo te koute, yo te kwè epi yo te thabalé, chak moun ki resevwa Dabar la dwe kite l transfòme lavi li. Se konsa qehilah la kontinye grandi, pa sèlman an kantite, men sitou nan fidelite ak matirite roḥanit.", "liy_final": "Émounah reyèl la pa rete nan pawòl sèlman; li mennen nan aksyon ki montre yon moun vrèman aksepte Dabar Yahawah la epi li dispoze kite l transfòme lavi li.", "mois": "Rebi'i"}, {"jour": 5, "soir_debut": "2026-06-20", "soir_fin": "2026-06-21", "ref": "Yaʿaqob 1:5", "texte_kw": "« Si youn nan nou manke bon konprann, se pou l kontinye mande 'Èlohim li, e l ap ba li l, paske l donan ak tout moun, e li pa fè repwòch. »", "commentaire": "Nan kòmansman lèt li a, Yaʿaqob ap ankouraje tal'midim yo pou yo kenbe fèm lè yo rankontre divès kalite eprèv. Li montre eprèv yo kapab ede yon moun devlope andirans ak matirite. Men, pou fè fas ak sitiyasyon sa yo yon fason ki fè Yahawah plezi, yon moun bezwen bon konprann.\n\nSe nan kontèks sa a Yaʿaqob di: \"Si youn nan nou manke bon konprann, se pou l kontinye mande 'Èlohim li.\" Bon konprann li pale a pa limite ak konesans oswa entèlijans. Li se kapasite pou konprann volonte Yahawah epi aplike Dabar Li a avèk bon jijman nan sitiyasyon lavi yo.\n\nYaʿaqob mete aksan sou jenewozite Yahawah. Li pa dekouraje moun ki pwoche bò kote Li avèk senserite; okontrè, Li dispoze bay direksyon ak bon konprann san Li pa fè repwòch moun ki mande avèk yon kè sensè.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo pa gen okenn wont pou rekonèt limit pa yo epi chèche direksyon Yahawah. Chak jou pote desizyon, defi ak eprèv ki mande plis pase eksperyans lèzòm; yo mande bon konprann ki soti nan Yahawah.\n\nLè yon tal'mid ap fè fas ak yon chwa enpòtan, yon pwoblèm fanmi, yon desizyon nan qehilah a oswa yon eprèv pèsonèl, li pa dwe konte sèlman sou pwòp refleksyon pa li. Li dwe hitpallél, etidye Ketubim Qadoshim yo epi chèche konprann prensip Yahawah yo pou l ka pran desizyon ki ann amoni ak volonte Li.\n\nPasaj sa a ankouraje Les Membres de La Voie yo tou pou yo gen konfyans nan jenerozite Yahawah. Lè yo mande Li bon konprann avèk émounah ak yon kè ki dispoze obeyi, yo kapab gen asirans Li ap gide yo atravè Dabar Li a epi ede yo mache sou bon chemen an.", "liy_final": "Vrè bon konprann pa soti nan kapasite lèzòm sèlman; li soti nan Yahawah e Li bay li avèk jenerozite bay moun ki chèche Li avèk yon kè sensè."}, {"jour": 6, "soir_debut": "2026-06-21", "soir_fin": "2026-06-22", "ref": "Yeshaʿeyahou 65:13", "texte_kw": "« Se poutèt sa, men sa Yahawah Adôn ki Souvren an di: 'Gade! ʿEbedim mwen yo ap manje, men nou menm n ap grangou. Gade! ʿEbedim mwen yo ap bwè, men nou menm n ap swaf. Gade! ʿEbedim mwen yo ap rejwi, men nou menm n ap wont.' »", "commentaire": "Nan dènye chapit liv Yeshaʿeyahou a, Yahawah fè yon diferans klè ant de kategori moun. Sou yon bò, gen moun ki vire do bay Li, ki suiv pwòp chemen pa yo epi ki meprize volonte Li. Sou lòt bò, gen ʿEbedim Li yo, moun ki chèche sèvi Li avèk fidelite epi ki dispoze koute Dabar Li a.\n\nSe nan kontèks sa a Yahawah anonse yon kontrast frapan: ʿEbedim Li yo ap jwenn manje, bwason ak lajwa, tandiske moun ki rejte Li yo ap fè eksperyans grangou, swaf ak wont. Pawòl sa yo sèvi pou montre benediksyon Yahawah pa depann sèlman de richès materyèl, men sitou de relasyon yon moun genyen avèk Li ak favè Li akòde a.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon ankourajman pou yo kontinye rete fidèl ak Yahawah menm lè yo ap viv nan yon monn ki souvan chwazi yon lòt direksyon. Yahawah pa bliye ʿEbedim Li yo. Li konnen bezwen yo epi Li pran swen yo selon volonte Li.\n\nPasaj la ankouraje tal'midim Yahushuʿah yo pou yo chèche an premye sa ki gen valè devan Yahawah. Menm lè yo konfwonte difikilte oswa privasyon, yo kapab gen konfyans Yahawah ap soutni yo epi ba yo sa yo bezwen pou kontinye mache sou chemen Li.\n\nAn menm tan, vèsè sa a envite chak moun egzamine pwòp pozisyon li. Èske li ap viv kòm yon ʿEbed Yahawah ki koute Dabar Li a, oswa èske li ap suiv pwòp volonte pa li? Vrè lajwa, vrè satisfaksyon ak vrè espwa jwenn rasin yo nan fidelite anvè Yahawah.", "liy_final": "Yahawah fè yon diferans ant moun ki sèvi Li avèk fidelite ak moun ki vire do bay Li. Se poutèt sa, Les Membres de La Voie yo chwazi mache kòm ʿEbedim Yahawah, avèk konfyans ke Li pap janm abandone moun ki rete atache ak Li."}, {"jour": 7, "soir_debut": "2026-06-22", "soir_fin": "2026-06-23", "ref": "Colossiyim 4:6", "texte_kw": "« Se pou pawòl nou toujou bèl, se pou l asezonnen ak sèl, yon fason pou n konnen jan n dwe reponn chak moun. »", "commentaire": "Nan fen lèt li te voye bay qehilah Coloss la, shilliaḥ Šāʾūl bay plizyè konsèy pratik sou fason pou tal'midim Yahushuʿah yo viv chak jou. Li ankouraje yo pou yo sèvi ak tan yo avèk bon jijman, sitou lè y ap pale ak moun ki pa fè pati qehilah a.\n\nSe nan kontèks sa a li di: \"Se pou pawòl nou toujou bèl, se pou l asezonnen ak sèl.\" Alò, nan tan lontan, sèl te sèvi pou konsève manje epi ba l bon gou. Menm jan an tou, pawòl yon tal'mid pa dwe ni brital ni san valè; pawòl yo dwe itil, ankourajan, reflechi epi adapte ak sitiyasyon chak moun.\n\nObjektif la se pou moun k ap pale a konnen kijan pou l bay yon repons ki montre l gen bon konprann, ki respekte laverite epi ki kapab ede moun k ap koute a.\n\nPou Membres La Voie yo, pasaj sa a raple yo pawòl yo gen anpil enpòtans. Yon tal'mid Yahushuʿah pa sèlman rekonèt apati de aksyon l sèlman, men tou pa fason l pale ak lòt moun. Kit se nan fanmi, nan travay, nan qehilah a oswa sou rezo sosyal yo, pawòl li dwe montre metriz, respè ak bon jijman.\n\n\"Asezonnen ak sèl\" vle di chwazi mo ki bati olye yo kraze, ki klè san yo pa blese initilman, epi ki fidèl ak Dabar Yahawah a. Sa pa vle di evite laverite, men pito prezante l avèk dousè, pasyans ak konsiderasyon pou moun k ap koute a.\n\nPasaj sa a ankouraje Membres La Voie yo tou pou yo adapte repons yo selon moun ak sikonstans yo. Gen moun ki bezwen ankourajman, gen lòt ki bezwen koreksyon, epi gen lòt ankò ki bezwen plis eksplikasyon. Bon jijman pèmèt yon tal'mid konnen ki pawòl ki pi apwopriye nan chak sitiyasyon.", "liy_final": "Pawòl ki soti nan bouch yon tal'mid Yahushuʿah dwe pote gou, limyè ak lavi, pou yo onore Yahawah epi ede lòt moun pwoche pi pre Dabar Li a."}, {"jour": 8, "soir_debut": "2026-06-23", "soir_fin": "2026-06-24", "ref": "1 Shemuʾel 17:45", "texte_kw": "« Ou menm, ou vin sou mwen ak nepe, ak frenn ak javlo; men mwen menm, mwen vin sou ou nan Non Yahawah Tseba'oth, 'Èlohim lame Yisra'el yo, Sila ou derespekte a. »", "commentaire": "Pasaj sa a pran plas pandan gwo konfwontasyon ant Dāwīḍ ak Golyath, yon vanyan sòlda filisten ki t ap defye pèp Yisra'el la epi k ap derespekte Non Yahawah. Pandan tout lame Yisra'el la te pè devan gwosè ak fòs Golyath, Dāwīḍ pa t kite aparans oswa zam advèsè li a fè l pè.\n\nLè Golyath vin sou li ak nepe, frenn ak javlo, Dāwīḍ reponn li avèk konfyans total nan Yahawah. Li fè konnen viktwa pa depann de fòs fizik oswa zam lagè, men de Yahawah Tseba'oth, Sila ki gen tout pouvwa e ki defann Non Li ak pèp Li. Pawòl Dāwīḍ yo montre batay la pa t sèlman ant de moun; se te yon kestyon fidelite anvè Yahawah ak respè pou Non Li.\n\nPou Les Membres de La Voie yo, pasaj sa a raple yo ke pi gwo sous fòs yon tal'mid pa chita nan kapasite pèsonèl li, ni nan resous materyèl li genyen, men nan konfyans li mete nan Yahawah. Nan lavi chak jou, anpil \"Golyath\" kapab parèt sou fòm eprèv, opozisyon, pèsekisyon, maladi oswa lòt defi ki sanble depase fòs nou.\n\nEgzanp Dāwīḍ ankouraje tal'midim Yahushuʿah yo pou yo pa kite laperèz oswa aparans sitiyasyon yo pran kontwòl sou yo. Lè yo rete fidèl ak Yahawah, yo ka avanse avèk kouraj, paske yo konnen se pa fòs lèzòm ki deside rezilta final la.\n\nPasaj sa a montre tou enpòtans pou toujou defann onè Non Yahawah avèk respè ak fidélité. Menm lè majorite a dekouraje oswa pè, yon sèl moun ki mete konfyans li nan Yahawah kapab sèvi kòm yon gwo temwayaj pou lòt moun.", "liy_final": "Lè yon tal'mid mete tout konfyans li nan Yahawah olye li konte sou fòs lèzòm, li aprann fè fas ak pi gwo eprèv yo avèk kouraj, paske li konnen Yahawah pa abandone moun ki rete fidèl ak Li."}, {"jour": 9, "soir_debut": "2026-06-24", "soir_fin": "2026-06-25", "ref": "Yeshaʿeyahou 41:10", "texte_kw": "« Ou pa bezwen pè, paske mwen avè w. Pa bay tèt ou pwoblèm, paske mwen se 'Èlohim ou. M ap ba w fòs, wi, m ap ede w. Vrèmanvre, m ap kenbe w byen di ak men dwat mwen pou m mennen w nan chemen ki dwat la. »", "commentaire": "Nan Yeshaʿeyahou chapit 41 la, Yahawah ap pale ak pèp Yisra'el la nan yon epòk kote yo t ap fè fas ak gwo menas, ensekirite ak dekourajman. Pandan nasyon ki ozalantou yo t ap mete konfyans yo nan zidòl ak nan pwòp fòs yo, Yahawah raple pèp Li a se Li menm ki te chwazi yo epi ki pa t abandone yo.\n\nSe nan kontèks sa a Li di: \"Ou pa bezwen pè, paske mwen avè w.\" Pawòl sa yo se yon mesaj rekonfò ak ankourajman. Yahawah pwomèt prezans Li, soutyen Li ak fòs Li pou moun ki mete konfyans yo nan Li. Men dwat Li mansyone a senbolize pouvwa, jistis ak fidelite Li pou gide ak soutni ʿEbedim Li yo.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon sous ankourajman nan tout kalite eprèv. Gen moman kote yon tal'mid ka santi l fèb, poukont li oswa enkyete devan difikilte lavi yo. Men Yahawah raple nou prezans Li pa depann de sikonstans yo; Li rete avèk moun ki chèche mache nan chemen Li.\n\nPasaj la ankouraje tal'midim Yahushuʿah yo pou yo pa kite laperèz dirije desizyon yo. Olye de sa, yo dwe chèche fòs nan Yahawah atravè hitpallah, etid Dabar Li a ak fidélité chak jou. Lè yon moun konte sou Yahawah, li jwenn kouraj pou kontinye menm lè chemen an difisil.\n\nAnplis, pwomès Yahawah pou \"kenbe nou byen di ak men dwat Li\" raple nou Li pa sèlman bay enstriksyon; Li soutni, gide epi ede moun ki rete fidèl yo. Sa envite Les Membres de La Voie yo pou yo mete tout konfyans yo nan Li olye yo konte sèlman sou kapasite pa yo oswa sou èd lèzòm.", "liy_final": "Lè yon tal'mid mache avèk Yahawah, li pa bezwen kite laperèz domine l, paske Yahawah pwomèt Li ap ba li fòs, ede l epi kenbe l fèm sou chemen ki dwat la."}, {"jour": 10, "soir_debut": "2026-06-25", "soir_fin": "2026-06-26", "ref": "Malʾakhi 3:18", "texte_kw": "« Yon lòt fwa ankò, n ap wè diferans ant yon moun ki jis ak yon moun ki mechan, ant yon moun k ap sèvi 'Èlohim ak yon moun ki pap sèvi l. »", "commentaire": "Nan dènye chapit liv Malʾakhi a, Yahawah reponn ak pawòl kèk moun ki t ap di li pa vo sèvi Li, paske yo te panse moun ki fè sa ki mal yo sanble ap reyisi pandan moun ki rete fidèl yo pa jwenn okenn avantaj. Anfas panse sa yo, Yahawah fè konnen Li wè tout bagay e Li pa bliye moun ki gen krentif pou Non Li.\n\nSe nan kontèks sa a Li pwomèt yon lè ap rive kote diferans lan ap parèt aklè. Moun ki mache nan jistis ak moun ki chwazi mechanste pap resevwa menm rezilta. Menm jan an tou, moun ki sèvi Yahawah fidèlman ak moun ki refize sèvi Li pap gen menm avni. Jijman Yahawah ap revele sa ki te pafwa kache nan je lèzòm.\n\nPou Les Membres de La Voie yo, pasaj sa a se yon envitasyon pou yo pa kite aparans twonpe yo. Nan monn jodi a, li ka sanble pafwa moun ki pa suiv chemen Yahawah la ap viv san pwoblèm oswa ap reyisi plis. Men Malʾakhi raple nou Yahawah pa jije selon aparans; Li konnen kè chak moun epi Li fè diferans ant fidelite ak ipokrizi.\n\nTal'midim Yahushuʿah yo pa dwe sèvi Yahawah sèlman pou benefis materyèl oswa pou yo jwenn lwanj nan men moun. Yo sèvi Li paske yo renmen Li, yo mete émounah yo nan Li epi yo rekonèt chemen Li se chemen lavi.\n\nPasaj sa a ankouraje chak manm La Voie pou l egzamine pwòp lavi li. Kesyon ki pi enpòtan an se pa sa lòt moun panse de nou, men si Yahawah rekonèt nou kòm moun k ap sèvi Li avèk yon kè sensè. Lè jou a rive kote Li fè diferans lan parèt aklè, se fidelite, obeyisans ak andirans ki pral konte.", "liy_final": "Yahawah pa janm konfonn moun ki sèvi Li ak moun ki vire do ba Li. Menm si diferans lan pa toujou parèt jodi a, lè Li a rive, Li menm ap fè l parèt aklè devan tout moun."}, {"jour": 11, "soir_debut": "2026-06-26", "soir_fin": "2026-06-27", "ref": "Éphésiyim 6:4", "texte_kw": "« E nou menm papa, pa nwi pitit nou jiskaske nou fè yo fache, men kontinye leve yo nan disiplin Yahawah ak nan avètisman Li bay. »", "commentaire": "Nan Éphésiyim chapit 6 la, shilliaḥ Šāʾūl bay enstriksyon sou relasyon ki dwe egziste anndan fanmi an. Apre li fin pale sou devwa timoun yo anvè paran yo, li vire bò kote papa yo epi li ba yo yon responsablite enpòtan. Li avèti yo pou yo pa trete pitit yo yon fason ki dekouraje yo, ki fè yo pèdi kouraj oswa ki pwovoke yo san rezon.\n\nOkontrè, Šāʾūl ankouraje yo pou yo leve pitit yo nan disiplin Yahawah ak nan avètisman ki soti nan Dabar Li a. Objektif disiplin sa a se pa kraze pitit la, men ede l grandi avèk bon prensip, bon jijman ak respè pou Yahawah.\n\nPou Les Membres de La Voie yo, pasaj sa a montre paran yo resevwa yon misyon sakre. Leve yon timoun pa sèlman vle di bay manje, rad oswa edikasyon; sa mande tou pou fòme karaktè li selon prensip Yahawah.\n\nPapa ak manman yo dwe evite move kòlè, enjistis, imilyasyon oswa egzije plis pase sa yon timoun kapab pote. Disiplin ki soti nan Yahawah chèche korije avèk lanmou, pasyans ak regilarite, pou pitit la aprann fè sa ki dwat pa konviksyon olye de laperèz.\n\nPasaj la ankouraje tout fanmi ki nan La Voie pou yo fè lakay yo tounen yon kote kote Dabar Yahawah li, etidye epi mete an pratik. Lè paran yo bay bon egzanp nan pawòl ak nan konduit yo, yo ede pitit yo devlope yon émounah solid epi prepare yo pou rete fidèl devan eprèv lavi yo.", "liy_final": "Disiplin ki baze sou Dabar Yahawah pa kraze yon timoun; li fòme l, pwoteje l epi prepare l pou l mache avèk fidelite sou chemen Yahawah pandan tout lavi li."}]}];